messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Three.js Low-Poly Humanoid Cycle</title>
    <style>
        body { margin: 0; overflow: hidden; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // Scene setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // Camera position (side-on view)
        camera.position.set(0, 1.5, 5);
        camera.lookAt(0, 1, 0);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);
        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(5, 5, 5);
        scene.add(directionalLight);

        // Ground (treadmill-style)
        const groundGeo = new THREE.PlaneGeometry(20, 2);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.01;
        scene.add(ground);

        // Low-poly humanoid (simplified stick figure with boxes)
        const bodyParts = [];
        const createBox = (width, height, depth, x, y, z) => {
            const geo = new THREE.BoxGeometry(width, height, depth);
            const mat = new THREE.MeshStandardMaterial({ color: 0x444444 });
            const mesh = new THREE.Mesh(geo, mat);
            mesh.position.set(x, y, z);
            scene.add(mesh);
            return mesh;
        };

        // Torso
        const torso = createBox(1, 2, 0.5, 0, 1, 0);
        bodyParts.push(torso);

        // Head
        const head = createBox(0.7, 0.7, 0.5, 0, 1.5, 0);
        bodyParts.push(head);

        // Left Arm
        const leftArm = createBox(0.5, 1, 0.5, -0.75, 1.25, 0);
        bodyParts.push(leftArm);

        // Right Arm
        const rightArm = createBox(0.5, 1, 0.5, 0.75, 1.25, 0);
        bodyParts.push(rightArm);

        // Left Leg
        const leftLeg = createBox(0.5, 2, 0.5, -0.25, 0, 0);
        bodyParts.push(leftLeg);

        // Right Leg
        const rightLeg = createBox(0.5, 2, 0.5, 0.25, 0, 0);
        bodyParts.push(rightLeg);

        // Animation state
        let state = 'stand'; // 'stand', 'walk', 'run'
        let phase = 0; // 0-100 for each state
        const walkSpeed = 0.02;
        const runSpeed = 0.05;
        const standTime = 200; // frames (2s @ 100fps)
        const walkTime = 300;  // 3s
        const runTime = 300;   // 3s
        const totalCycle = standTime + walkTime + runTime + standTime;

        // Position and rotation offsets for limbs during animation
        const limbOffsets = {
            leftArm: { swing: 0, lean: 0 },
            rightArm: { swing: 0, lean: 0 },
            leftLeg: { swing: 0, lean: 0 },
            rightLeg: { swing: 0, lean: 0 }
        };

        // Animation loop
        let lastTime = 0;
        const clock = new THREE.Clock();

        function animate() {
            const now = clock.getElapsedTime();
            const deltaTime = now - lastTime;
            lastTime = now;

            // Update animation state
            if (state === 'stand') {
                phase = (phase + deltaTime * 100) % totalCycle;
                if (phase < standTime) {
                    // Stand still
                    updateLimbs(0);
                } else if (phase < standTime + walkTime) {
                    state = 'walk';
                    phase = phase - standTime;
                } else if (phase < standTime + walkTime + runTime) {
                    state = 'run';
                    phase = phase - standTime - walkTime;
                } else {
                    state = 'stand';
                    phase = phase - standTime - walkTime - runTime;
                }
            } else {
                phase = (phase + deltaTime * 100) % totalCycle;
                if (state === 'walk' && phase >= walkTime) {
                    state = 'stand';
                    phase = 0;
                } else if (state === 'run' && phase >= runTime) {
                    state = 'stand';
                    phase = 0;
                }
            }

            // Update limb positions based on state and phase
            updateLimbs(phase);

            renderer.render(scene, camera);
            requestAnimationFrame(animate);
        }

        function updateLimbs(phase) {
            // Reset all limb offsets
            for (const part in limbOffsets) {
                limbOffsets[part].swing = 0;
                limbOffsets[part].lean = 0;
            }

            if (state === 'walk') {
                // Walking: moderate swing, alternating legs
                const walkPhase = phase / walkTime * 100;
                limbOffsets.leftArm.swing = Math.sin(walkPhase * Math.PI / 50) * 0.3;
                limbOffsets.rightArm.swing = -limbOffsets.leftArm.swing;
                limbOffsets.leftLeg.swing = Math.sin(walkPhase * Math.PI / 50) * 0.2;
                limbOffsets.rightLeg.swing = -limbOffsets.leftLeg.swing;
                limbOffsets.leftLeg.lean = Math.sin(walkPhase * Math.PI / 25) * 0.1;
                limbOffsets.rightLeg.lean = -limbOffsets.leftLeg.lean;
            } else if (state === 'run') {
                // Running: larger swing, forward lean
                const runPhase = phase / runTime * 100;
                limbOffsets.leftArm.swing = Math.sin(runPhase * Math.PI / 25) * 0.6;
                limbOffsets.rightArm.swing = -limbOffsets.leftArm.swing;
                limbOffsets.leftLeg.swing = Math.sin(runPhase * Math.PI / 15) * 0.4;
                limbOffsets.rightLeg.swing = -limbOffsets.leftLeg.swing;
                limbOffsets.leftLeg.lean = Math.sin(runPhase * Math.PI / 15) * 0.15;
                limbOffsets.rightLeg.lean = -limbOffsets.leftLeg.lean;
                torso.rotation.z = Math.sin(runPhase * Math.PI / 15) * 0.05;
            }

            // Apply offsets to limbs
            torso.rotation.z = limbOffsets.leftLeg.lean + limbOffsets.rightLeg.lean;

            leftArm.rotation.y = limbOffsets.leftArm.swing;
            rightArm.rotation.y = limbOffsets.rightArm.swing;

            leftLeg.rotation.x = limbOffsets.leftLeg.swing + limbOffsets.leftLeg.lean;
            rightLeg.rotation.x = limbOffsets.rightLeg.swing + limbOffsets.rightLeg.lean;
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation immediately
        animate();
    </script>
</body>
</html>
```
